"""Review the actual saved model without promoting it to art acceptance."""
from pathlib import Path
import hashlib,json,re,subprocess
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/creature-models/2026-10-13/rift-titan-strata-r4'
row=json.loads((OUT/'refinement-metrics.json').read_text(encoding='utf-8'));ID=row['id']
checks=json.loads((OUT/'verification.json').read_text(encoding='utf-8'));contacts=json.loads((OUT/'attachment-verification.json').read_text(encoding='utf-8'))
assert checks['source_sha256']==hashlib.sha256((ROOT/row['source']).read_bytes()).hexdigest()
assert checks['triangles']==row['triangles']<=1800 and contacts['result']=='PASS'
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rift Titan — strata and supported cage r4</title>
<style>body{{background:#14191c;color:#e4e5df;font:16px system-ui;max-width:1500px;margin:auto;padding:24px}}p{{line-height:1.6;max-width:1150px}}a{{color:#9ccdda}}img{{width:100%;object-fit:contain;background:#171e22}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}figure{{margin:0}}figcaption{{padding:8px;color:#bbc5c6}}button{{background:#283840;color:#e4e5df;border:1px solid #60747a;padding:8px 14px;margin:5px;cursor:pointer}}@media(max-width:800px){{.pair{{grid-template-columns:1fr}}}}</style>
<h1>Rift Titan — strata and supported cage r4</h1><p>The online plate-layout and fracture-facet changes are now present in the saved model: longer plates follow the limb bones, shoulder layers are thinner, and plate faces have shallow fracture ridges. The chest cage has closed hoops and both ends of every diagonal brace seated into them.</p>
<p><strong>{row['triangles']:,} triangles · {row['ratio']:.3f}× native Stone Golem · soft cap 1,800</strong>. One mesh/material, four 512px maps, eight rig bones and seven retained actions. Eight brace contacts pass 35 sampled poses. These checks establish the saved geometry and contacts; this is an unaccepted art candidate.</p>
<h2>Before and after — same view</h2><div><button data-view="three-quarter">Surface</button><button data-view="clay">Clay</button><button data-view="front">Front</button><button data-view="side">Side</button><button data-view="detail">Core</button></div><div class="pair"><figure><img id="before" src="../../2026-10-12/rift-titan-primary-r3/underworld-boss-rift-titan-primary-r3--three-quarter.png" alt="Preserved primary r3"><figcaption>Previous r3 — short stacked plates and loose-ended cage braces</figcaption></figure><figure><img id="after" src="{ID}--three-quarter.png" alt="Saved strata and cage r4"><figcaption>Current r4 — longer bone-aligned strata, thinner shoulders, supported cage</figcaption></figure></div>
<h2>Adopted concept</h2><img src="../../../creature-concepts/2026-10-03/the-rift-titan.png" alt="Rift Titan concept, front, side and binding cage detail">
<h2>Native donor quality reference</h2><img style="max-width:900px" src="../../2026-10-04/detail-r2/donor-StoneGolem--three-quarter.png" alt="Extracted native Stone Golem reference"><p>The donor is the visual quality and cost reference. Passing the cap does not establish comparable art quality.</p>
<h2>Remaining refinement</h2><p>The concept still needs closer matching of crown and shoulder masses, denser-looking layered fracture surfaces, and individualized weathered stone/lichen detail. Native loader admission, complete deformation review and live performance remain pending. First Bloom remains the only adequately reworked boss in the rolling tally; Blackwater remains paused.</p>
<p><a href="../../../../../{row['source']}">Editable Blender model</a> · <a href="{ID}.glb">Skinned export</a> · <a href="{ID}--attack.png">Inherited attack pose</a> · <a href="verification.json">Geometry and export checks</a> · <a href="attachment-verification.json">Cage contact checks</a> · <a href="cage-authoring.json">Cage construction</a> · <a href="provenance.json">Source provenance</a></p>
<script>document.querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>{{document.getElementById('before').src='../../2026-10-12/rift-titan-primary-r3/underworld-boss-rift-titan-primary-r3--'+b.dataset.view+'.png';document.getElementById('after').src='{ID}--'+b.dataset.view+'.png';}});</script></html>'''
sources=['tools/rift_titan_primary_refinement.py','tools/rift_titan_primary_layout.py','tools/rift_titan_rock_facets.py','tools/rift_titan_cage_refinement.py','tools/refine-rift-titan-strata-r4.py','tools/review-rift-titan-strata-r4.py','tools/verify-rift-titan-cage-r4.py',row['source'],'docs/art/creature-concepts/2026-10-03/the-rift-titan.png']
(OUT/'provenance.json').write_text(json.dumps(dict(base_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sources},acceptance='unaccepted primary-form candidate; tally remains 1/6'),indent=2)+'\n',encoding='utf-8')
(OUT/'gallery.html').write_text(html,encoding='utf-8')
for target in re.findall(r'(?:href|src)="([^"]+)"',html):assert (OUT/target).resolve().is_file(),target
print('VERIFIED r4 review links, cap and saved source hash')
